class MockAgent(Agent):
    """Mock agent for testing without API calls."""

    def __init__(self, responses: List[str] = None, **kwargs):
        super().__init__("mock-model", **kwargs)
        self.responses = responses or ["Mock response"]
        self.call_count = 0

    def generate(self, prompt: str, system_prompt: Optional[str] = None) -> str:
        """Return predetermined responses for testing."""
        response = self.responses[self.call_count % len(self.responses)]
        self.call_count += 1

        # Add to conversation history
        if system_prompt:
            self.conversation_history.append(Message("system", system_prompt))
        self.conversation_history.append(Message("user", prompt))
        self.conversation_history.append(Message("assistant", response))

        return response


def create_agent(provider: str, model_name: str, **kwargs) -> Agent:
    """
    Factory function to create agents.

    Args:
        provider: 'openai', 'anthropic', or 'mock'
        model_name: Specific model to use
        **kwargs: Additional arguments passed to agent constructor

    Returns:
        Agent instance
    """
    if provider == "openai":
        return OpenAIAgent(model_name=model_name, **kwargs)
    elif provider == "anthropic":
        return AnthropicAgent(model_name=model_name, **kwargs)
    elif provider == "mock":
        return MockAgent(**kwargs)
    else:
        raise ValueError(f"Unknown provider: {provider}")
